import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.YT-FC_Xx.js";const p=JSON.parse('{"title":"新建入站","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodes.md","filePath":"guide/nodes.md","lastUpdated":1792771754000}'),o={name:"guide/nodes.md"};function n(i,t,s,l,h,g){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="新建入站" tabindex="-1">新建入站 <a class="header-anchor" href="#新建入站" aria-label="Permalink to &quot;新建入站&quot;">​</a></h1><p>入站是内核上的一个代理服务，客户端连的就是它。所有配置由面板生成，服务器上的 agent 只负责下载内核、写入配置、运行和守护进程。</p><p>开始前：服务器已 <a href="./agent">安装 agent</a> 并在线，并装好了内核（见 <a href="./kernels">内核与协议</a>）。</p><h2 id="创建" tabindex="-1">创建 <a class="header-anchor" href="#创建" aria-label="Permalink to &quot;创建&quot;">​</a></h2><p><strong>节点</strong> 页 → <strong>入站</strong> 标签 → <strong>新建入站</strong> → 选择服务器和内核 → 点击一个快速模板 → 填名称 → <strong>创建并下发</strong>。</p><p>端口留空会随机分配，UUID、密码、密钥留空会自动生成。</p><h2 id="快速模板" tabindex="-1">快速模板 <a class="header-anchor" href="#快速模板" aria-label="Permalink to &quot;快速模板&quot;">​</a></h2><p>模板只填好协议、传输和安全层，创建后都可以再改。</p><table tabindex="0"><thead><tr><th>模板</th><th>内核</th><th>说明</th></tr></thead><tbody><tr><td>VLESS + Reality + Vision</td><td>Xray / sing-box</td><td>推荐，无需域名和证书</td></tr><tr><td>VLESS + Encryption + Vision</td><td>Xray</td><td>抗量子加密，无需域名和证书；客户端需 Xray 25.9+ 或 Mihomo</td></tr><tr><td>VLESS + XHTTP + Reality</td><td>Xray</td><td></td></tr><tr><td>Shadowsocks 2022</td><td>Xray / sing-box</td><td></td></tr><tr><td>Trojan + TLS（自签）</td><td>Xray / sing-box</td><td>需要填写域名</td></tr><tr><td>VMess + WS + TLS</td><td>Xray / sing-box</td><td>兼容老客户端</td></tr><tr><td>Hysteria2</td><td>sing-box</td><td>基于 QUIC，可选端口跳跃</td></tr><tr><td>TUIC v5</td><td>sing-box</td><td>基于 QUIC</td></tr><tr><td>AnyTLS</td><td>sing-box</td><td></td></tr><tr><td>SS2022 + ShadowTLS</td><td>sing-box</td><td>仅 TCP</td></tr><tr><td>NaïveProxy</td><td>sing-box</td><td>需要域名和真实证书</td></tr><tr><td>WireGuard</td><td>Xray / sing-box</td><td>所有人共用一份客户端配置；分享里有配置文件和二维码，WireGuard 官方 App 可直接导入</td></tr><tr><td>SOCKS5 / HTTP 代理</td><td>Xray / sing-box</td><td>不加密，适合内网或经加密线路中转后使用；订阅用户各有自己的用户名和密码</td></tr><tr><td>Snell / Snell + ShadowTLS</td><td>sing-box（1.14+）/ Snell</td><td>Surge 专用；两个内核的区别见 <a href="./kernels#snell-用哪个内核">Snell 用哪个内核</a></td></tr></tbody></table><h2 id="证书" tabindex="-1">证书 <a class="header-anchor" href="#证书" aria-label="Permalink to &quot;证书&quot;">​</a></h2><p>TLS 类入站有三种证书来源：</p><ul><li><strong>自动生成自签证书</strong>：开箱即用，客户端需要允许不安全证书（分享链接已自动带上）</li><li><strong>使用服务器上的证书文件</strong>：填写证书和私钥在服务器上的绝对路径</li><li><strong>自动申请证书（ACME）</strong>：仅 sing-box，需要 1.14 及以上 <ul><li>域名必须解析到该服务器</li><li>HTTP 验证：服务器 80 端口要能从公网访问</li><li>DNS 验证：支持 Cloudflare（API Token）和阿里云（AccessKey），不需要 80 端口</li><li>证书由 sing-box 自动续期</li></ul></li></ul><p>NaïveProxy 必须使用真实证书（ACME 或证书文件）。</p><h2 id="hysteria2-端口跳跃" tabindex="-1">Hysteria2 端口跳跃 <a class="header-anchor" href="#hysteria2-端口跳跃" aria-label="Permalink to &quot;Hysteria2 端口跳跃&quot;">​</a></h2><p>在 Hysteria2 入站里填写一段 UDP 端口，例如 <code>20000-30000</code>。服务器会用 nftables 把这段端口转到入站端口，客户端在其中随机切换，缓解运营商对单个 UDP 端口的限速。</p><ul><li>范围不能包含入站端口本身，不能和其他入站、转发或服务器的转发端口段重叠</li><li>只有直连地址带跳跃参数；经中转连接时只转发一个端口，不跳跃</li></ul><h2 id="监听地址" tabindex="-1">监听地址 <a class="header-anchor" href="#监听地址" aria-label="Permalink to &quot;监听地址&quot;">​</a></h2><p>默认监听 <code>::</code>（同时支持 IPv4 和 IPv6）。如果服务器在内核启动参数里完全禁用了 IPv6（<code>ipv6.disable=1</code>），部分内核会绑定失败，此时在高级选项里把监听地址改为 <code>0.0.0.0</code>。</p><h2 id="分享" tabindex="-1">分享 <a class="header-anchor" href="#分享" aria-label="Permalink to &quot;分享&quot;">​</a></h2><p>点击入站 → <strong>分享</strong>（电脑上也可以直接点行内的“分享”按钮）：显示通用分享链接和二维码；WireGuard 显示配置文件和二维码；Snell 没有通用链接，显示 Surge 配置行。</p><p>日常使用建议用 <a href="./subscription">订阅</a>：一个链接包含选中的节点和中转线路，换了参数客户端更新一下就行。</p><h2 id="入站上的其他操作" tabindex="-1">入站上的其他操作 <a class="header-anchor" href="#入站上的其他操作" aria-label="Permalink to &quot;入站上的其他操作&quot;">​</a></h2><p>点击入站可以：</p><ul><li><strong>中转</strong>：把隧道接到这个入站上，见 <a href="./relay">对接中转</a></li><li><strong>分流</strong>：服务器侧的分流和链式出站，见 <a href="./routing">分流与链式出站</a></li><li><strong>参数</strong>：查看完整的协议参数</li><li><strong>延迟</strong>：卡片上的延迟可以点开看各测试点、趋势和回程，见 <a href="./latency">延迟与回程</a></li></ul><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><p>入站多了不好管理时，点列表上方的 <strong>多选</strong>：点卡片勾选，<strong>全选</strong> 会选中当前列表里显示的全部入站（可以先用搜索或服务器筛选缩小范围），然后可以批量 <strong>启用</strong>、<strong>停用</strong> 或 <strong>删除</strong>。每个受影响的内核只下发一次配置。</p><p>下一步：<a href="./routing">分流与链式出站</a> · <a href="./relay">对接中转</a></p>',27)])])}const u=a(o,[["render",n]]);export{p as __pageData,u as default};
